package dev.zyon;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
import net.minecraft.init.Bootstrap;import net.minecraft.init.Items;import net.minecraft.item.*;import net.minecraft.util.ResourceLocation;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class ArmorCitTest {
 @Rule public TemporaryFolder temporary=new TemporaryFolder();
 @BeforeClass public static void registry(){Bootstrap.register();}
 private ArmorCitRule rule(String type,String range,int id,String folder){Properties p=new Properties();p.setProperty("type",type);p.setProperty("items",Integer.toString(id));p.setProperty("damage",range);p.setProperty(type.equals("armor")?"texture.diamond_layer_"+(id==312?2:1):"texture",type.equals("armor")?"armor_layer"+(id==312?2:1):"diamond_icon");return new ArmorCitRule(new ResourceLocation("minecraft","mcpatcher/cit/"+folder+"/armor.properties"),p,1);}
 @Test public void original911BandsMatchWornArmorAndIconsAtEveryDamageValue(){for(Item item:new Item[]{Items.diamond_helmet,Items.diamond_chestplate,Items.diamond_leggings,Items.diamond_boots})for(String type:new String[]{"armor","item"}){int id=Item.getIdFromItem(item);ArmorCitRule green=rule(type,"20%-50%",id,"Green"),yellow=rule(type,"51%-85%",id,"Yellow"),red=rule(type,"86%-100%",id,"Red");ItemStack stack=new ItemStack(item);for(int damage=0;damage<=stack.getMaxDamage();damage++){stack.setItemDamage(damage);int percent=(int)(damage*100L/stack.getMaxDamage());assertEquals(percent>=20&&percent<=50,green.matches(stack));assertEquals(percent>=51&&percent<=85,yellow.matches(stack));assertEquals(percent>=86,red.matches(stack));}}}
 @Test public void chestHelmetBootsUseLayerOneAndLeggingsUseLayerTwo(){for(int id:new int[]{310,311,312,313}){ArmorCitRule r=rule("armor","86%-100%",id,"Red");ItemStack item=new ItemStack(Item.getItemById(id));item.setItemDamage(item.getMaxDamage());int slot=id==310?4:id==311?3:id==312?2:1;ResourceLocation location=r.armorTexture(item,slot,new ResourceLocation("minecraft","textures/models/armor/diamond_layer_"+(slot==2?2:1)+".png"));assertEquals("mcpatcher/cit/Red/armor_layer"+(slot==2?2:1)+".png",location.getResourcePath());assertNull(r.armorTexture(item,slot,new ResourceLocation("minecraft","textures/models/armor/leather_layer_1_overlay.png")));}}
 @Test public void conditionsNeverRecolorOtherMaterialsOrIgnoreStackLimits(){ArmorCitRule r=rule("item","20%-50%",310,"Green");ItemStack iron=new ItemStack(Items.iron_helmet);iron.setItemDamage(80);assertFalse(r.matches(iron));Properties p=new Properties();p.setProperty("items","310");p.setProperty("damage","10-20");p.setProperty("stackSize","1");ArmorCitRule count=new ArmorCitRule(new ResourceLocation("mcpatcher/cit/test.properties"),p,0);ItemStack helmet=new ItemStack(Items.diamond_helmet,2,15);assertFalse(count.matches(helmet));helmet.stackSize=1;assertTrue(count.matches(helmet));}
 @Test public void texturePathsPreservePackCaseAndStayInAssetDomain(){ResourceLocation source=new ResourceLocation("minecraft","mcpatcher/cit/Green/helmet.properties");assertEquals("minecraft:mcpatcher/cit/Green/diamond_helmet.png",ArmorCitRule.texture(source,"diamond_helmet").toString());assertEquals("minecraft:mcpatcher/cit/Red/icon.png",ArmorCitRule.texture(source,"../Red/icon.png").toString());assertEquals("minecraft:textures/items/icon.png",ArmorCitRule.texture(source,"textures/items/icon").toString());try{ArmorCitRule.texture(source,"../../../../../../escape");fail();}catch(IllegalArgumentException expected){}}
 @Test public void scanningZipAndFolderUsesOnlyCitAndRejectsTraversal()throws Exception{File dir=temporary.newFolder();Path file=dir.toPath().resolve("assets/minecraft/mcpatcher/cit/Green/helmet.properties");Files.createDirectories(file.getParent());Files.write(file,new byte[0]);assertEquals(1,ArmorCit.propertyPaths(dir,Collections.singleton("minecraft")).size());File archive=temporary.newFile("pack.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(archive))){for(String name:new String[]{"assets/minecraft/optifine/cit/a.properties","assets/minecraft/mcpatcher/cit/../../escape.properties","assets/minecraft/mcpatcher/sky/clouds.properties"}){zip.putNextEntry(new ZipEntry(name));zip.closeEntry();}}assertEquals(Collections.singletonList("assets/minecraft/optifine/cit/a.properties"),ArmorCit.propertyPaths(archive,Collections.singleton("minecraft")));}
}
